def schema_bug(record, contract):
    from decimal import Decimal, InvalidOperation
    from math import isfinite

    id_val = record.get("id")
    if not isinstance(id_val, str):
        raise ContractError("id must be a string")

    amount = record.get("amount")
    if amount is None:
        raise ContractError("amount is required")

    try:
        if isinstance(amount, str):
            d_amount = Decimal(amount)
        elif isinstance(amount, int):
            d_amount = Decimal(amount)
        elif isinstance(amount, float):
            if not isfinite(amount):
                raise ContractError("amount must be finite")
            d_amount = Decimal(str(amount))
        else:
            raise ContractError("invalid amount type")
    except (InvalidOperation, ValueError):
        raise ContractError("invalid amount")

    if not d_amount.is_finite():
        raise ContractError("amount must be finite")

    amount_unit = contract.get("amount_unit")
    if amount_unit not in ("major", "minor"):
        raise ContractError("amount unit needs confirmation")

    if amount_unit == "minor":
        minor = d_amount
    else:
        minor = d_amount * 100

    if minor % 1 != 0:
        raise ContractError("amount must be integer minor units")

    amount_minor = int(minor)

    return {"id": id_val, "amount_minor": amount_minor}

