def normalize_invoice(record):
    id_val = record["id"]
    amount_str = record["amount"]
    from decimal import Decimal
    try:
        amount_dec = Decimal(amount_str)
    except Exception:
        raise ContractError(f"Invalid amount: {amount_str}")
    if not amount_dec.is_finite():
        raise ContractError(f"Non-finite amount: {amount_str}")
    minor = amount_dec * 100
    if minor % 1 != 0:
        raise ContractError(f"Fractional minor units from amount: {amount_str}")
    amount_minor = int(minor)
    return {"id": id_val, "amount_minor": amount_minor}

