        raise ContractError("invalid amount")

    if d.is_infinite() or d.is_nan():
        raise ContractError("invalid amount")

    if amount_unit == "minor":
        if not d.is_integer():
            raise ContractError("fractional minor-unit amount")
        minor = int(d)
    else:
        scaled = d * 100
        if not scaled.is_integer():
            raise ContractError("fractional minor-unit amount")
        minor = int(scaled)

    return {"id": id_val, "amount_minor": minor}

